import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { caseNames, EXPECTED_DIR, renderCase } from "./render-case.ts";

/**
 * W-925 (D-065): stored pages from 0.x (schema 10, 15, 16 and 17 documents) still upgrade and
 * render byte for byte as they did before the 1.0 schema freeze. Expected output was rendered
 * by 0.9.0 (commit 165f33a8) and is never regenerated by a test.
 */
describe("0.x pages render unchanged after the schema freeze (W-925)", () => {
  test("the corpus is not empty", () => {
    expect(caseNames().length).toBeGreaterThanOrEqual(10);
  });
  for (const name of caseNames()) {
    test(name, () => {
      const expected = JSON.parse(readFileSync(join(EXPECTED_DIR, `${name}.json`), "utf8")) as {
        html: string;
        css: string;
      };
      const actual = renderCase(name);
      expect(actual.html).toBe(expected.html);
      expect(actual.css).toBe(expected.css);
    });
  }
});
